import{_ as d,o as e,c as a,ag as r}from"./chunks/framework.CvgP6Fyv.js";const m=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md"}'),o={name:"api.md"};function i(c,t,n,s,l,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>Dendrite exposes a REST API for configuration and control, and WebSocket channels for real-time data. When the backend is running, interactive API docs are available at <code>/docs</code> (Swagger UI).</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/pipeline/start</code></td><td>POST</td><td>Start processing pipeline</td></tr><tr><td><code>/api/pipeline/stop</code></td><td>POST</td><td>Stop pipeline</td></tr><tr><td><code>/api/pipeline/status</code></td><td>GET</td><td>Pipeline state (recording, elapsed, PIDs)</td></tr><tr><td><code>/api/pipeline/preflight</code></td><td>GET</td><td>Run pre-start validation checks</td></tr><tr><td><code>/api/pipeline/debug</code></td><td>GET</td><td>Data flow diagnostics</td></tr><tr><td><code>/api/pipeline/viz-preprocessing</code></td><td>GET/PUT</td><td>Visualization preprocessing config</td></tr><tr><td><code>/api/pipeline/channel-flags</code></td><td>GET/PUT</td><td>Manual bad channel flags for interpolation</td></tr><tr><td><code>/api/pipeline/session-events</code></td><td>GET</td><td>Unique event codes seen in current session</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/config</code></td><td>GET</td><td>Get full current configuration</td></tr><tr><td><code>/api/config/general</code></td><td>GET/PUT</td><td>Study name, subject ID, session ID</td></tr><tr><td><code>/api/config/output</code></td><td>GET/PUT</td><td>Output protocol settings</td></tr><tr><td><code>/api/config/output/availability</code></td><td>GET</td><td>Which output protocols have dependencies installed</td></tr><tr><td><code>/api/config/output/defaults</code></td><td>GET</td><td>Default config values for each output protocol</td></tr><tr><td><code>/api/config/load?file_path=...</code></td><td>POST</td><td>Load config from JSON</td></tr><tr><td><code>/api/config/save</code></td><td>POST</td><td>Save config to JSON</td></tr><tr><td><code>/api/config/next-run</code></td><td>GET</td><td>Next auto-incremented run number for subject/session</td></tr><tr><td><code>/api/config/list</code></td><td>GET</td><td>List saved config files</td></tr></tbody></table><h2 id="streams" tabindex="-1">Streams <a class="header-anchor" href="#streams" aria-label="Permalink to &quot;Streams&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/streams</code></td><td>GET</td><td>Get configured streams</td></tr><tr><td><code>/api/streams/discover</code></td><td>POST</td><td>Discover LSL streams on network</td></tr><tr><td><code>/api/streams/configure</code></td><td>POST</td><td>Configure selected streams</td></tr><tr><td><code>/api/streams/liveness</code></td><td>GET</td><td>Check if configured streams are still available</td></tr></tbody></table><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/modes</code></td><td>GET/POST</td><td>List/create mode instances</td></tr><tr><td><code>/api/modes/{name}</code></td><td>GET/PUT/DELETE</td><td>Get/update/remove mode instance</td></tr><tr><td><code>/api/modes/{name}/start</code></td><td>POST</td><td>Start mode during recording</td></tr><tr><td><code>/api/modes/{name}/stop</code></td><td>POST</td><td>Stop mode during recording</td></tr><tr><td><code>/api/modes/{name}/state</code></td><td>GET</td><td>Get mode component state</td></tr><tr><td><code>/api/modes/{name}/rename</code></td><td>POST</td><td>Rename mode instance</td></tr></tbody></table><h2 id="websocket-channels" tabindex="-1">WebSocket Channels <a class="header-anchor" href="#websocket-channels" aria-label="Permalink to &quot;WebSocket Channels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Format</th><th>Description</th></tr></thead><tbody><tr><td><code>/ws/visualization</code></td><td>msgpack (~100Hz)</td><td>Raw signal data (decimated 5×, preprocessed)</td></tr><tr><td><code>/ws/telemetry</code></td><td>JSON (1Hz)</td><td>CPU, memory, stream health, latency, channel quality</td></tr><tr><td><code>/ws/mode_data</code></td><td>msgpack</td><td>Mode output data (predictions, ERP, band power)</td></tr><tr><td><code>/ws/training</code></td><td>JSON</td><td>Decoder training progress</td></tr></tbody></table><h2 id="data-explorer" tabindex="-1">Data Explorer <a class="header-anchor" href="#data-explorer" aria-label="Permalink to &quot;Data Explorer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/data/studies</code></td><td>GET/POST</td><td>List/create studies</td></tr><tr><td><code>/api/data/studies/{id}</code></td><td>GET/PUT/DELETE</td><td>Study CRUD</td></tr><tr><td><code>/api/data/studies/import-folder</code></td><td>POST</td><td>Scan folder for .h5 files, register under study</td></tr><tr><td><code>/api/data/studies/pick-folder</code></td><td>POST</td><td>Native OS folder picker for study import</td></tr><tr><td><code>/api/data/recordings</code></td><td>GET</td><td>List recordings (filterable, searchable)</td></tr><tr><td><code>/api/data/recordings/{id}</code></td><td>GET/DELETE</td><td>Recording detail/delete</td></tr><tr><td><code>/api/data/recordings/{id}/file-info</code></td><td>GET</td><td>HDF5 file structure</td></tr><tr><td><code>/api/data/recordings/{id}/channels</code></td><td>GET</td><td>Channel labels, count, sample rate</td></tr><tr><td><code>/api/data/recordings/{id}/signal-preview</code></td><td>GET</td><td>Signal preview data</td></tr><tr><td><code>/api/data/recordings/{id}/erp</code></td><td>GET</td><td>ERP preview (epoch/filter params)</td></tr><tr><td><code>/api/data/recordings/{id}/qc-preview</code></td><td>GET</td><td>Signal quality preview</td></tr><tr><td><code>/api/data/recordings/{id}/event-summary</code></td><td>GET</td><td>Event summary</td></tr><tr><td><code>/api/data/recordings/{id}/summary</code></td><td>GET</td><td>Session summary</td></tr><tr><td><code>/api/data/recordings/{id}/telemetry</code></td><td>GET</td><td>Historical telemetry data</td></tr><tr><td><code>/api/data/recordings/{id}/mode-performance</code></td><td>GET</td><td>Mode performance metrics</td></tr><tr><td><code>/api/data/decoders</code></td><td>GET</td><td>List decoders (filterable, searchable)</td></tr><tr><td><code>/api/data/decoders/{id}</code></td><td>GET/DELETE</td><td>Decoder detail/delete</td></tr><tr><td><code>/api/data/decoders/{id}/metadata</code></td><td>GET</td><td>Full decoder metadata (event/label mappings) from saved JSON</td></tr></tbody></table><h2 id="ml-training" tabindex="-1">ML Training <a class="header-anchor" href="#ml-training" aria-label="Permalink to &quot;ML Training&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/ml/models</code></td><td>GET</td><td>List available model types</td></tr><tr><td><code>/api/ml/models/{type}/schema</code></td><td>GET</td><td>Model config JSON schema</td></tr><tr><td><code>/api/ml/load-recording</code></td><td>POST</td><td>Load recording for ML training</td></tr><tr><td><code>/api/ml/data/loaded</code></td><td>GET</td><td>Loaded data metadata</td></tr><tr><td><code>/api/ml/moabb/datasets</code></td><td>GET</td><td>List MOABB datasets</td></tr><tr><td><code>/api/ml/moabb/load</code></td><td>POST</td><td>Load MOABB dataset</td></tr><tr><td><code>/api/ml/train</code></td><td>POST</td><td>Start training job</td></tr><tr><td><code>/api/ml/train/{job_id}/cancel</code></td><td>POST</td><td>Cancel training job</td></tr><tr><td><code>/api/ml/jobs</code></td><td>GET</td><td>List training jobs</td></tr><tr><td><code>/api/ml/jobs/{id}</code></td><td>GET</td><td>Job status</td></tr><tr><td><code>/api/ml/jobs/{id}</code></td><td>DELETE</td><td>Delete a job record</td></tr><tr><td><code>/api/ml/jobs/{id}/reaggregate</code></td><td>POST</td><td>Re-aggregate eval results with new decision gate</td></tr><tr><td><code>/api/ml/jobs/{id}/save-decoder</code></td><td>POST</td><td>Save trained model as named decoder</td></tr><tr><td><code>/api/ml/search-categories/{decoder_type}</code></td><td>GET</td><td>Available search categories for a decoder type</td></tr><tr><td><code>/api/ml/evaluate</code></td><td>POST</td><td>Epoch-by-epoch decoder evaluation</td></tr><tr><td><code>/api/ml/benchmark</code></td><td>POST</td><td>K-fold CV benchmark across models</td></tr></tbody></table><h2 id="stream-manager" tabindex="-1">Stream Manager <a class="header-anchor" href="#stream-manager" aria-label="Permalink to &quot;Stream Manager&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/stream-manager/start</code></td><td>POST</td><td>Start file/MOABB replay stream</td></tr><tr><td><code>/api/stream-manager/stop/{id}</code></td><td>POST</td><td>Stop a replay stream</td></tr><tr><td><code>/api/stream-manager/status</code></td><td>GET</td><td>Active stream status</td></tr><tr><td><code>/api/stream-manager/pick-file</code></td><td>POST</td><td>Open native file picker</td></tr><tr><td><code>/api/stream-manager/file-info</code></td><td>POST</td><td>Get file metadata</td></tr><tr><td><code>/api/stream-manager/moabb</code></td><td>GET</td><td>List MOABB datasets</td></tr><tr><td><code>/api/stream-manager/datasets</code></td><td>GET</td><td>List internal datasets</td></tr></tbody></table><h2 id="health" tabindex="-1">Health <a class="header-anchor" href="#health" aria-label="Permalink to &quot;Health&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/api/health</code></td><td>GET</td><td>Health check</td></tr></tbody></table>',20)])])}const b=d(o,[["render",i]]);export{m as __pageData,b as default};
